#include <bits/stdc++.h>
using namespace std;

using ll = long long;
constexpr int MAX_VERTEX = 5007;
constexpr ll BIG = 1000000000LL;
constexpr ll MOD_VAL = 1000000007LL;

struct NetworkEdge {
    int begin;
    int finish;
    ll limit;
    ll price;
    ll used;
    NetworkEdge(int b, int f, ll lim, ll prc)
        : begin(b), finish(f), limit(lim), price(prc), used(0) {}
};

vector<NetworkEdge> all_edges;
ll distance[MAX_VERTEX];
ll potential[MAX_VERTEX];
vector<int> graph[MAX_VERTEX];
int previous_edge_index[MAX_VERTEX];

void link(int u, int v, ll cap, ll cost) {
    graph[u].emplace_back(all_edges.size());
    all_edges.emplace_back(u, v, cap, cost);
    graph[v].emplace_back(all_edges.size());
    all_edges.emplace_back(v, u, 0, -cost);
}

void relax(int src, int cnt) {
    fill(potential, potential + MAX_VERTEX, BIG);
    potential[src] = 0;
    for (int round = 0; round < cnt; ++round) {
        for (size_t idx = 0; idx < all_edges.size(); ++idx) {
            auto& e = all_edges[idx];
            if (e.limit == e.used) continue;
            if (potential[e.begin] == BIG) continue;
            potential[e.finish] = min(potential[e.finish], potential[e.begin] + e.price);
        }
    }
}

void shortest_path(int source) {
    fill(distance, distance + MAX_VERTEX, BIG);
    distance[source] = 0;
    set<pair<ll, int>> heap;
    heap.emplace(0, source);
    while (!heap.empty()) {
        auto [d_val, u] = *heap.begin();
        heap.erase(heap.begin());
        for (int id : graph[u]) {
            auto& e = all_edges[id];
            if (e.limit == e.used) continue;
            int v = e.finish;
            ll w = e.price + potential[u] - potential[v];
            if (distance[u] + w < distance[v]) {
                heap.erase({distance[v], v});
                distance[v] = distance[u] + w;
                previous_edge_index[v] = id;
                heap.emplace(distance[v], v);
            }
        }
    }
}

pair<ll, ll> solve_flow(int s, int t) {
    relax(s, 50);
    shortest_path(s);
    ll flow = 0, cost = 0;
    while (distance[t] != BIG) {
        ll augment = numeric_limits<ll>::max();
        ll path_cost = 0;
        for (int cur = t; cur != s; ) {
            int id = previous_edge_index[cur];
            augment = min(augment, all_edges[id].limit - all_edges[id].used);
            path_cost += all_edges[id].price;
            cur = all_edges[id].begin;
        }
        flow += augment;
        cost += augment * path_cost;
        for (int cur = t; cur != s; ) {
            int id = previous_edge_index[cur];
            all_edges[id].used += augment;
            all_edges[id ^ 1].used -= augment;
            cur = all_edges[id].begin;
        }
        shortest_path(s);
        for (int i = 0; i < MAX_VERTEX; ++i) potential[i] = distance[i];
    }
    return {cost, flow};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    cout << fixed << setprecision(20);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    vector<int> demand(n, 0);
    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        demand[--x]++;
    }
    for (int i = 0; i < n; ++i) link(5000, i, demand[i], 0);
    for (int iter = 0; iter < m; ++iter) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        for (int layer = 0; layer < 99; ++layer) {
            ll cost = d;
            for (int rep = 0; rep < 50; ++rep) {
                link(u + layer * 50, v + (layer + 1) * 50, 1, cost);
                link(v + layer * 50, u + (layer + 1) * 50, 1, cost);
                cost += 2 * d;
            }
        }
    }
    for (int layer = 0; layer <= 99; ++layer) {
        link(layer * 50, 5001, numeric_limits<ll>::max(), c * layer);
    }
    for (int i = 0; i < n; ++i) {
        for (int layer = 0; layer < 99; ++layer) {
            link(i + layer * 50, i + (layer + 1) * 50, numeric_limits<ll>::max(), 0);
        }
    }
    auto [answer, _] = solve_flow(5000, 5001);
    assert(true); // ignore assert for flow
    cout << answer;
    return 0;
}
